import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
/**
 * Installing the omp adapter.
 *
 * omp discovers extensions as loose modules in its own directory, so the
 * adapter cannot simply live in this repo and be found. What gets installed is
 * a three-line shim that re-exports the built adapter by absolute path, so all
 * the real code stays here, under test and under version control, and the
 * installed file has nothing in it worth editing.
 *
 * The absolute path matters: a symlink would resolve relative imports through
 * its target, but a copy would not, and users copy things. An absolute
 * re-export works either way.
 *
 * This is the same shape herdr uses for its own omp integration — a generated,
 * clearly-marked file that the installer owns and rewrites.
 */
export const INSTALLED_FILENAME = "ua-memory.ts";
/** Written into the shim so a later install knows the file is ours to replace. */
const SIGNATURE = "ua-memory:omp-adapter";
/** omp's user-level extension directory. */
export function defaultOmpExtensionsDir() {
    return join(homedir(), ".omp", "agent", "extensions");
}
/**
 * Absolute path to the compiled adapter this package ships.
 *
 * Resolved from the package root rather than relative to this module, because
 * this file runs from `dist/` in production and straight from `src/` under
 * vitest. Anchoring on package.json gives the same answer either way.
 */
export function adapterPath() {
    let dir = dirname(fileURLToPath(import.meta.url));
    for (;;) {
        if (existsSync(join(dir, "package.json")))
            return join(dir, "dist", "omp.js");
        const up = dirname(dir);
        if (up === dir)
            throw new Error("ua-memory: could not find the package root");
        dir = up;
    }
}
function shimSource(target) {
    return [
        `// ${SIGNATURE}`,
        "// Generated by `ua-memory omp install` — do not edit.",
        "// The adapter itself lives in the ua-memory package; re-run the installer to update it.",
        "// @ts-nocheck",
        `export { default } from "${target}";`,
        "",
    ].join("\n");
}
function isOurs(path) {
    try {
        return readFileSync(path, "utf8").includes(SIGNATURE);
    }
    catch {
        return false;
    }
}
export function ompInstall(extensionsDir = defaultOmpExtensionsDir()) {
    const target = adapterPath();
    if (!existsSync(target)) {
        throw new Error(`ua-memory: the adapter is not built. Expected ${target}. Run \`npm run build\` first.`);
    }
    const path = join(extensionsDir, INSTALLED_FILENAME);
    const exists = existsSync(path);
    if (exists && !isOurs(path)) {
        throw new Error(`ua-memory: ${path} exists and was not written by ua-memory. Move it aside first.`);
    }
    mkdirSync(extensionsDir, { recursive: true });
    writeFileSync(path, shimSource(target), "utf8");
    return { path, target, replaced: exists };
}
export function ompStatus(extensionsDir = defaultOmpExtensionsDir()) {
    const path = join(extensionsDir, INSTALLED_FILENAME);
    if (!existsSync(path) || !isOurs(path)) {
        return { path, installed: false, target: null, stale: false };
    }
    const target = readFileSync(path, "utf8").match(/from "([^"]+)"/)?.[1] ?? null;
    return { path, installed: true, target, stale: !target || !existsSync(target) };
}
export function ompUninstall(extensionsDir = defaultOmpExtensionsDir()) {
    const path = join(extensionsDir, INSTALLED_FILENAME);
    if (!existsSync(path) || !isOurs(path))
        return { removed: false };
    rmSync(path, { force: true });
    return { removed: true };
}
